lemma eq_bot_iff_card {G : Type*} [Group G] {H : Subgroup G} :
    H = ⊥ ↔ Nat.card H = 1  := by
  simp [eq_bot_iff_forall, Nat.card_eq_one_iff_exists, Type Cylinder];

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  simp [← H.index_eq_card, H.index_mul_card, h', mul_comm, mul_left_eq_self] at ⊢;

