lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  calc _ * Nat.card H = _ := by rw [← H.index_eq_card, H.index_mul_card] at ⊢;

theorem iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H   := by
  apply MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K)
  rw [Nat.bijective_iff_injective_and_card, ⟨← ker_eq_bot_iff, (QuotientGroup.mk' H).ker_restrict K⟩, aux_card_eq h']");
